import React from "react";
import { Input, Form, Select } from "antd";

export function getFormItems(formData, form) {
  const { getFieldDecorator } = form;
  const {
    fieldName,
    type: Type,
    label = " ",
    initialValue,
    required = false,
    disabled = false,
    isMultiple,
  } = formData;

  const { type } = Type;
  switch (type) {
    case "string": {
      const options = formData?.type?.options;
      if (options && Array.isArray(options)) {
        return (
          <Form.Item
            label={<b style={{ fontSize: "12px" }}>{label}</b>}
            key={label}
            style={{ width: "100%" }}
          >
            {getFieldDecorator(fieldName, {
              initialValue: handleGetDefaultValue(initialValue, fieldName),
              rules: [
                {
                  required: required,
                  message: `Please enter ${label}`,
                },
              ],
            })(
              <Select
                mode={isMultiple ? "multiple" : undefined}
                showSearch
                placeholder={
                  isMultiple ? "Select one or more" : "Select an option"
                }
                disabled={disabled}
                className="dropdown-input"
                filterOption={(input, option) =>
                  option.props.children
                    .toLowerCase()
                    .indexOf(input.toLowerCase()) >= 0
                }
                style={{ width: "100%" }}
              >
                {options?.length > 0 &&
                  options.map((option, index) => {
                    return (
                      <Select.Option
                        key={index}
                        value={option.key ? option.key : option}
                      >
                        {option.value ? option.value : option}
                      </Select.Option>
                    );
                  })}
              </Select>
            )}
          </Form.Item>
        );
      }
      return (
        <Form.Item
          label={<b style={{ fontSize: "12px" }}>{label}</b>}
          key={label}
        >
          {getFieldDecorator(fieldName, {
            initialValue: handleGetDefaultValue(initialValue, fieldName),
            rules: [
              {
                required: required,
                message: `Please enter ${label}`,
              },
            ],
          })(<Input disabled={fieldName === "reference_id"} />)}
        </Form.Item>
      );
    }
    case "number": {
      return (
        <Form.Item
          label={<b style={{ fontSize: "12px" }}>{label}</b>}
          key={label}
        >
          {getFieldDecorator(fieldName, {
            initialValue: handleGetDefaultValue(initialValue, fieldName),
            rules: [
              {
                required: required,
                message: `Please enter ${label}`,
              },
            ],
          })(<Input type="number" />)}
        </Form.Item>
      );
    }
    default:
      return null;
  }
}

const handleGetDefaultValue = (values, key) => {
  if (Array.isArray(values)) {
    const item = values.find((item) => item?.key === key);
    return item ? item.value : "";
  }
  return values;
};
