import { Button, Card, Col, Icon, notification, Row, Spin, Table, Tag } from "antd";
import { LayoutWrapper } from "./index.style";
import { useCallback, useEffect, useState } from "react";
import WrappedEditForm from "./components/addEditModal";
import QuerySearchBuilder from "../../../helpers/querySearchBuilder";
import { connect } from "react-redux";
import financialActions from "../../../PasarApp/redux/tapInsure/actions";
import moment from "moment-timezone";
import { useLocation, useHistory } from "react-router";
import {
  FilterInput,
  FilterSelectOption,
} from "../../../components/tables/helperCells";
import PermissionChecker from "../../../components/permissionChecker";

const { getWorkshopList, resetReportingConfigRedux } = financialActions;

const MONTH_MAP = {
  1: "January",
  2: "February",
  3: "March",
  4: "April",
  5: "May",
  6: "June",
  7: "July",
  8: "August",
  9: "September",
  10: "October",
  11: "November",
  12: "December",
};

const WorkshopList = (props) => {
  const [openEditForm, setOpenEditForm] = useState(false);
  const [selectedRecord, setSelectedRecord] = useState(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [searchTextQuery, setSearchTextQuery] = useState({});
  const [isChange, setIsChange] = useState(false);
  const [isFilterVisible, setIsFilterVisible] = useState("");
  const [filters, setFilters] = useState({})

  const {
    getWorkshopList,
    workshopList = [],
    tableDataSourceLoading,
    addUpdateMessage,
    resetReportingConfigRedux,
    permissions,
  } = props;

  const location = useLocation();
  const history = useHistory();

  const searchParams = new URLSearchParams(location.search);
  const defaultPage = parseInt(searchParams.get("page") || "1", 10);

  useEffect(() => {
    setCurrentPage(defaultPage);
    getWorkshopList({
      category: "monthly-financial-report, annual-financial-report",
      page: defaultPage,
      offset: defaultPage * 15,
      limit: 15,
      ordering: '-updated_at',
      ...searchTextQuery,
    });
  }, [location.search]);

  const handlePageChange = (pagination) => {
    const newPage = pagination.current;
    setCurrentPage(newPage);
    const search = QuerySearchBuilder({ page: newPage });
    history.push({ pathname: location.pathname, search });
  };

  useEffect(() => {
    if (addUpdateMessage) {
      notification[addUpdateMessage === "success" ? "success" : "error"]({
        message:
          addUpdateMessage === "success"
            ? `Config ${selectedRecord ? 'Updated' : 'Added'} Successfully!`
            : "Error Occurred!",
      });
      resetReportingConfigRedux(["addUpdateMessage"]);
      setOpenEditForm(false)
      const newParams = new URLSearchParams(location.search);
      const page = parseInt(newParams.get("page") || "1", 10);
      getWorkshopList({
        category: "monthly-financial-report, annual-financial-report",
        page,
        offset: defaultPage * 15,
        limit: 15,
        ordering: '-updated_at',
        ...searchTextQuery,
      });
    }
  }, [addUpdateMessage]);

  useEffect(() => {
    return () => {
      resetReportingConfigRedux([
        "addUpdateMessage",
        "workshopList",
        "workshoplListMessage",
      ]);
    };
  }, []);

  const handleClose = () => {
    setOpenEditForm(false);
    setSelectedRecord(null);
  };

  const handleOpen = (record = null) => {
    setSelectedRecord(record);
    setOpenEditForm(true);
  };

  const handleDownload = (url) => {
    if (url) {
      window.open(url, "_blank");
    }
  };

  const handleInputChange = useCallback(
    (event, identifier) => {
      setSearchTextQuery({
        ...searchTextQuery,
        [identifier]: event.target.value,
      });
      setIsChange(true);
    },
    [searchTextQuery]
  );

  function convertMonthNumberToName(query) {
    const monthNum = parseInt(query.month, 10);
    const monthName = MONTH_MAP[monthNum];
  
    const { month, ...rest } = query;
  
    return monthName
      ? { ...rest, month: monthName }
      : { ...rest };
  }

  const handleSearch = (e) => {
    e.preventDefault();
    setIsFilterVisible("");
    setFilters(convertMonthNumberToName(searchTextQuery))
    getWorkshopList({
      category: "monthly-financial-report, annual-financial-report",
      page: defaultPage,
      offset: defaultPage * 15,
      limit: 15,
      ordering: '-updated_at',
      ...searchTextQuery,
    });
  };

  const handleResetFilter = (key) => {
    const updatedQuery = { ...searchTextQuery };
    delete updatedQuery[key];

    setSearchTextQuery(updatedQuery);
    setFilters(convertMonthNumberToName(updatedQuery))
    setIsChange(true);
    setIsFilterVisible("");

    const search = QuerySearchBuilder({ ...updatedQuery });
    history.push({ pathname: location.pathname, search });
    getWorkshopList({
      category: "monthly-financial-report, annual-financial-report",
      page: defaultPage,
      offset: defaultPage * 15,
      limit: 15,
      ordering: '-updated_at',
      ...updatedQuery,
    });
  };

  const handleClearAllFilters = () => {
    setSearchTextQuery({});
    setFilters({})
    setIsChange(true);
    setIsFilterVisible("");
  
    const search = QuerySearchBuilder({ page: 1 });
    history.push({ pathname: location.pathname, search });
  
    getWorkshopList({
      category: "monthly-financial-report, annual-financial-report",
      page: 1,
      offset: 15,
      limit: 15,
      ordering: '-updated_at',
    });
    setCurrentPage(1);
  };
  
  const columns = [
    {
      key: "actions",
      title: "Actions",
      render: (_, record) => (
        <div style={{ display: "flex", gap: "20px", justifyContent: 'center' }}>
          <Icon
            type="download"
            style={{ color: "#1890ff", cursor: "pointer", fontSize: 20 }}
            onClick={() => handleDownload(record?.link)}
          />
          <PermissionChecker
            permissionSetter="ops.tapinsure-add-edit-financial-reports"
            permissionGetter={permissions}
          >
            <Icon
              type="edit"
              style={{ color: "#fa8c16", cursor: "pointer", fontSize: 20 }}
              onClick={() => handleOpen(record)}
            />
          </PermissionChecker>
        </div>
      ),
    },
    {
      key: "title",
      title: "Name",
      dataIndex: "title",
      render: (data) => data || "-",
      filterDropdown: (
        <div style={{ padding: 8 }}>
          <FilterInput
            idIdentifier="title"
            className=""
            searchText={isChange ? searchTextQuery.name : ""}
            onInputChange={(e) => handleInputChange(e, "name")}
            onSearch={(e) => handleSearch(e, "name")}
          />
          <Button
            size="small"
            style={{ marginTop: 8, width: "100%" }}
            onClick={() => handleResetFilter("name")}
          >
            Reset
          </Button>
        </div>
      ),
      filterDropdownVisible: isFilterVisible === "title",
      onFilterDropdownVisibleChange: (visible) =>
        setIsFilterVisible(visible ? "title" : searchTextQuery.title),
    },
    {
      key: "category",
      title: "Category",
      dataIndex: "category",
      render: (data) => data || "-",
      filterDropdown: (
        <div style={{ padding: 8 }}>
          <FilterSelectOption
            searchText={isChange ? searchTextQuery.category : ""}
            onInputChange={(e) => handleInputChange(e, "category")}
            onSearch={(e) => handleSearch(e, "category")}
            optionData={["monthly-financial-report", "annual-financial-report"]}
          />
          <Button
            size="small"
            style={{ marginTop: 8, width: "100%" }}
            onClick={() => handleResetFilter("category")}
          >
            Reset
          </Button>
        </div>
      ),
      filterDropdownVisible: isFilterVisible === "category",
      onFilterDropdownVisibleChange: (visible) =>
        setIsFilterVisible(visible ? "category" : searchTextQuery.category),
    },
    {
      key: "month",
      title: "Month",
      dataIndex: "month",
      render: (data) => MONTH_MAP[data] || "-",
      filterDropdown: (
        <div style={{ padding: 8 }}>
          <FilterSelectOption
            searchText={isChange ? searchTextQuery.month : ""}
            onInputChange={(e) => handleInputChange(e, "month")}
            onSearch={(e) => handleSearch(e, "month")}
            optionData={[
              { name: "January", value: 1 },
              { name: "February", value: 2 },
              { name: "March", value: 3 },
              { name: "April", value: 4 },
              { name: "May", value: 5 },
              { name: "June", value: 6 },
              { name: "July", value: 7 },
              { name: "August", value: 8 },
              { name: "September", value: 9 },
              { name: "October", value: 10 },
              { name: "November", value: 11 },
              { name: "December", value: 12 },
            ]}
          />
          <Button
            size="small"
            style={{ marginTop: 8, width: "100%" }}
            onClick={() => handleResetFilter("month")}
          >
            Reset
          </Button>
        </div>
      ),
      filterDropdownVisible: isFilterVisible === "month",
      onFilterDropdownVisibleChange: (visible) =>
        setIsFilterVisible(visible ? "month" : searchTextQuery.month),
    },
    {
      key: "year",
      title: "Year",
      dataIndex: "year",
      render: (data) => data || "-",
      filterDropdown: (
        <div style={{ padding: 8 }}>
          <FilterInput
            idIdentifier="year"
            className=""
            searchText={isChange ? searchTextQuery.year : ""}
            onInputChange={(e) => handleInputChange(e, "year")}
            onSearch={(e) => handleSearch(e, "year")}
          />
          <Button
            size="small"
            style={{ marginTop: 8, width: "100%" }}
            onClick={() => handleResetFilter("year")}
          >
            Reset
          </Button>
        </div>
      ),
      filterDropdownVisible: isFilterVisible === "year",
      onFilterDropdownVisibleChange: (visible) =>
        setIsFilterVisible(visible ? "year" : searchTextQuery.year),
    },
    {
      key: "active",
      title: "Active",
      dataIndex: "is_active",
      render: (val) => (
        <b style={{ color: val ? "green" : "red" }}>{val ? "True" : "False"}</b>
      ),
    },
    {
      key: "created_at",
      title: "Created At",
      dataIndex: "created_at",
      render: (data) => (data ? moment(data).format("YYYY-MM-DD HH:mm") : "-"),
    },
    {
      key: "updated_at",
      title: "Updated At",
      dataIndex: "updated_at",
      render: (data) => (data ? moment(data).format("YYYY-MM-DD HH:mm") : "-"),
    },
    {
      key: "created_by",
      title: "User",
      dataIndex: "created_by",
      render: (data) => data || "-",
    },
  ];

  const removeFilter = filterKeyToBeRemoved => {
    const updatedQuery = searchTextQuery

    delete updatedQuery[filterKeyToBeRemoved]

    setSearchTextQuery(updatedQuery)
    const searchQuery = QuerySearchBuilder(updatedQuery)
    history.push({ pathname: location.pathname, search: searchQuery })
    getWorkshopList({
        category: "monthly-financial-report, annual-financial-report",
        page: defaultPage,
        offset: defaultPage * 15,
        limit: 15,
        ordering: '-updated_at',
        ...updatedQuery
      });
  }

  const getFilterTag = (filters, key) => {
    return Object.keys(filters).map((key, value) =>
      <Tag
        className='top-filter'
        key={key}
        color='purple'
        closable='closable'
        onClose={() => removeFilter(key)}
      >
        {key}: {filters[key]}
      </Tag>
    )
  }

  return (
    <LayoutWrapper>
      <Card>
        <Row type="flex" justify="space-between">
          <Col>
            <h1 className="label-name">
              <b>Publication Report: {workshopList?.metadata?.count}</b>
            </h1>
            {getFilterTag(filters)}
          </Col>
          <Col>
            <PermissionChecker
              permissionSetter="ops.tapinsure-add-edit-financial-reports"
              permissionGetter={permissions}
            >
              <div className="button__section" style={{ display: "flex", gap: 10 }}>
                <Button onClick={handleClearAllFilters}>Clear Filters</Button>
                <Button type="primary" onClick={() => handleOpen()}>
                  <b>+ Add Report</b>
                </Button>
              </div>
            </PermissionChecker>
          </Col>
        </Row>

        <div className="table-container">
          <Spin
            spinning={tableDataSourceLoading}
            tip="Reporting List Loading ..."
          >
            <Table
              bordered
              columns={columns}
              dataSource={workshopList.results}
              rowKey={(record) => record.id}
              pagination={{
                pageSize: 15,
                current: currentPage,
                total: workshopList?.metadata?.count,
              }}
              onChange={handlePageChange}
            />
          </Spin>
        </div>
      </Card>

      {openEditForm && (
        <WrappedEditForm onCancel={handleClose} formData={selectedRecord} />
      )}
    </LayoutWrapper>
  );
};

export default connect(
  (state) => ({
    workshopList: state.TapInsureConfigurable.workshopList,
    workshoplListMessage: state.TapInsureConfigurable.workshoplListMessage,
    tableDataSourceLoading: state.Loading.GET_WORKSHOP_REPORTS,
    addUpdateData: state.TapInsureConfigurable.addUpdateData,
    addUpdateMessage: state.TapInsureConfigurable.addUpdateMessage,
  }),
  {
    getWorkshopList,
    resetReportingConfigRedux,
  }
)(WorkshopList);
