import React, { useState, useEffect } from "react";
import { Form, Modal, Upload, Button, Icon, notification } from "antd";
import { connect } from "react-redux";
import { isEqual, size } from "lodash";
import { getFormItems } from "./getFormItems";
import policyActions from "../../../../redux/policy/actions";
import tapInsureActions from "../../../../../src/PasarApp/redux/tapInsure/actions";

const { uploadPolicyFile, resetReduxState: policyResetReduxState } =
  policyActions;
const { addUpdateReport } = tapInsureActions;

const EditForm = (props) => {
  const {
    form,
    editFormRef,
    inputEditable,
    onCancel,
    uploadPolicyFileData,
    uploadPolicyFileStatus,
    uploadPolicyFile,
    policyResetReduxState,
    userData,
    addUpdateReport,
    formData = null,
  } = props;

  const { setFieldsValue, getFieldsValue } = form;

  const [fileUrl, setFileUrl] = useState(null);
  const [filename, setFilename] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [formBody, setFormBody] = useState({});
  const [documentUrls, setDocumentUrls] = useState([]);

  const allowedExtensions = ["pdf"];

  useEffect(() => {
    if (formData) {
      const fields = {
        ...formData,
        link: formData.link ? [formData.link] : [],
        is_active: formData.is_active ? 'True' : 'False'
      };
      setFieldsValue(fields);

      if (formData.link) {
        setFileUrl(formData.link);
        setFilename(formData.link.split("/").pop());
        setDocumentUrls([{ url: formData.link }]);
      }
    }
  }, [formData]);

  useEffect(() => {
    if (uploadPolicyFileStatus === "success" && uploadPolicyFileData?.url) {
      const newUrl = uploadPolicyFileData.url;
      const newFile = newUrl.split("/").pop();
      setFileUrl(newUrl);
      setFilename(newFile);
      setDocumentUrls([{ url: newUrl }]);
      setFieldsValue({ link: [newUrl] });
      setUploading(false);
      policyResetReduxState(["uploadPolicyFileStatus", "uploadPolicyFileData"]);
    }
  }, [uploadPolicyFileStatus]);

  const checkFileExtension = (filename) => {
    const fileExtension = filename.split(".").pop().toLowerCase();
    return allowedExtensions.includes(fileExtension);
  };

  const handleUploadChange = async (info) => {
    if (info?.file?.status === "done" || info?.file?.status === "error") {
      const file = info.file.originFileObj;
      if (!checkFileExtension(info?.file?.name)) {
        notification.error({ message: "Invalid file type. Please upload a PDF format." });
        return;
      }
      try {
        const formData = new FormData();
  
        let originalName = file.name.split(".")[0];
        let cleanedName = originalName.replace(/\s+/g, "").replace(/[^a-zA-Z0-9]/g, "_");
  
        formData.append("file", file);
        formData.append("path", `publication/${cleanedName}_${Date.now()}`);
        formData.append("identifier", "b2c");
  
        uploadPolicyFile({ body: formData });
        setUploading(true);
      } catch (error) {
        notification.error({ message: "Upload failed" });
        setUploading(false);
      }
    }
  };

  const handleRemoveFile = () => {
    setFileUrl(null);
    setFilename(null);
    setDocumentUrls([]);
    setFieldsValue({ link: [] });
  };

  const validateForm = () => {
    return new Promise((resolve) => {
      form.validateFields((err) => {
        if (err) {
          notification.error({ message: "Please fill all required fields" });
          resolve(false);
        } else {
          resolve(true);
        }
      });
    });
  };

  const submitHandler = async (e) => {
    e.preventDefault();
    const valid = await validateForm();
    if (!valid) return;

    const currentFormData = getFieldsValue();
    if (size(formBody) > 0 && isEqual(formBody, currentFormData)) {
      console.log("Form unchanged");
    } else {
      const docUrl = documentUrls.map((doc) => doc.url).join(",");
      const newFormBody = {
        ...currentFormData,
        link: docUrl,
        created_by: userData?.email,
        is_active: currentFormData.is_active ? currentFormData.is_active === 'True' ? true : false : true,
        ...(formData?.id ? { id: formData.id } : {}), // add id only in edit
      };
      setFormBody(newFormBody);
      addUpdateReport(newFormBody);
    }
  };

  return (
    <Modal
      visible={!inputEditable}
      title={formData ? "Edit Publication Report" : "Add Publication Report"}
      okText="Submit"
      cancelText="Cancel"
      onCancel={onCancel}
      onOk={submitHandler}
      destroyOnClose
    >
      <div>
        <Form ref={editFormRef}>
          {getFormItems(
            {
              fieldName: "title",
              type: { type: "string" },
              label: "Name",
              initialValue: formData?.title || "",
              required: true,
            },
            form
          )}
          {getFormItems(
            {
              fieldName: "category",
              type: {
                type: "string",
                options: [
                  {
                    key: "monthly-financial-report",
                    value: "Monthly Financial Report",
                  },
                  {
                    key: "annual-financial-report",
                    value: "Annual Financial Report",
                  },
                ],
              },
              label: "Category",
              initialValue: formData?.category || "",
              required: true,
            },
            form
          )}
          {getFieldsValue().category === 'monthly-financial-report' && getFormItems(
            {
              fieldName: "month",
              type: {
                type: "string",
                options: Array.from({ length: 12 }, (_, i) => ({
                  key: i + 1,
                  value: new Date(0, i).toLocaleString("default", {
                    month: "long",
                  }),
                })),
              },
              label: "Month",
              initialValue: formData?.month || "",
              required: true,
            },
            form
          )}
          {getFormItems(
            {
              fieldName: "year",
              type: { type: "number" },
              label: "Year",
              initialValue: formData?.year || "",
              required: true,
            },
            form
          )}
          {formData &&
            getFormItems(
              {
                fieldName: "is_active",
                type: {
                  type: "string",
                  options: [
                    { key: 'True', value: "True" },
                    { key: 'False', value: "False" },
                  ],
                },
                label: "Is Active",
                initialValue: formData?.is_active ?? true,
                required: true,
              },
              form
            )}

          <Form.Item
            label={<b style={{ fontSize: "12px" }}>Upload Document</b>}
          >
            {form.getFieldDecorator("link", {
              initialValue: formData?.link ? [formData.link] : [],
              rules: [{ required: true, message: `Please upload document` }],
            })(
              <Upload
                name="documents"
                showUploadList={false}
                multiple={false}
                customRequest={({ onSuccess }) =>
                  setTimeout(() => onSuccess("ok"), 0)
                }
                onChange={handleUploadChange}
              >
                <div style={{display: 'flex', flexDirection: 'column', gap: '6px'}}>
                  <Button disabled={uploading}>
                    <Icon type="upload" /> {uploading ? "Uploading..." : "Upload"}
                  </Button>
                  <b style={{fontSize: '10px', color: 'red'}}>* pdf only</b>
                </div>
              </Upload>
            )}
            {fileUrl && (
              <div style={{ marginTop: 10 }}>
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    marginBottom: 6,
                  }}
                >
                  <span>
                    <Icon type="file" style={{ marginRight: 8 }} />
                    {filename}
                  </span>
                  <Icon
                    type="delete"
                    style={{ color: "red", cursor: "pointer" }}
                    onClick={handleRemoveFile}
                  />
                </div>
              </div>
            )}
          </Form.Item>
        </Form>
      </div>
    </Modal>
  );
};

const WrappedEditForm = Form.create()(EditForm);

export default connect(
  (state) => ({
    userData: state.Auth.profile,
    uploadPolicyFileStatus: state.Insurance.uploadPolicyFileStatus,
    uploadPolicyFileData: state.Insurance.uploadPolicyFileData,

    addUpdateData: state.TapInsureConfigurable.addUpdateData,
    addUpdateMessage: state.TapInsureConfigurable.addUpdateMessage,
  }),
  {
    uploadPolicyFile,
    policyResetReduxState,
    addUpdateReport,
  }
)(WrappedEditForm);
